int sas_get_phy_event_counts(struct sas_phy *phy) {
    struct {
        __u8 cmd;
        __u8 phy_id;
    } __attribute__((packed)) *req;
    struct {
        __u32 rx_frame_errors;
        __u32 rx_link_reset_ins;
        __u32 rx_link_reset_outs;
        __u32 rx_oob_frames;
        __u32 tx_frames;
        __u32 tx_link_reset_ins;
        __u32 tx_link_reset_outs;
    } __attribute__((packed)) *resp;
    int ret = -ENOMEM;

    req = kzalloc(sizeof(*req), GFP_KERNEL);
    if (!req)
        goto out;

    resp = kzalloc(sizeof(*resp), GFP_KERNEL);
    if (!resp)
        goto out_free_req;

    req->cmd = SAS_GET_PHY_EVENT_COUNTS;
    req->phy_id = phy->number;

    ret = sas_execute_task(phy->port, req, sizeof(*req), resp, sizeof(*resp));
    if (ret < 0)
        goto out_free_resp;

    phy->rx_frame_errors = be32_to_cpu(resp->rx_frame_errors);
    phy->rx_link_reset_ins = be32_to_cpu(resp->rx_link_reset_ins);
    phy->rx_link_reset_outs = be32_to_cpu(resp->rx_link_reset_outs);
    phy->rx_oob_frames = be32_to_cpu(resp->rx_oob_frames);
    phy->tx_frames = be32_to_cpu(resp->tx_frames);
    phy->tx_link_reset_ins = be32_to_cpu(resp->tx_link_reset_ins);
    phy->tx_link_reset_outs = be32_to_cpu(resp->tx_link_reset_outs);
    ret = 0;

out_free_resp:
    kfree(resp);
out_free_req:
    kfree(req);
out:
    return ret;
}

int sas_get_phy_event_counts(struct sas_phy *phy)
{
    struct request *req;
    void *resp;
    int result = 0;
    int ret = 0;

    req = alloc_request();
    if (!req)
        return -ENOMEM;

    resp = kmalloc(EVENT_BUF_SIZE, GFP_KERNEL);
    if (!resp) {
        ret = -ENOMEM;
        goto out_free_req;
    }

    initialize_request(req, GET_PHY_EVENT_CMD, phy->number);
    result = execute_task(req, resp, EVENT_BUF_SIZE);
    if (result < 0) {
        ret = result;
        goto out_free_resp;
    }

    phy->disparity_errors = get_field(resp, DISPARITY_ERRORS_OFFSET);
    phy->loss_of_sync = get_field(resp, LOSS_OF_SYNC_OFFSET);
    phy->primitive_errors = get_field(resp, PRIMITIVE_ERRORS_OFFSET);
    phy->link_reset_out = get_field(resp, LINK_RESET_OUT_OFFSET);
    phy->link_reset_in = get_field(resp, LINK_RESET_IN_OFFSET);

out_free_resp:
    kfree(resp);
out_free_req:
    free_request(req);
    return ret;
}

int get_sas_phy_event_counts(struct sas_phy *phy) {
    void *request;
    void *response;
    int result;

    request = kmalloc(REQUEST_SIZE, GFP_KERNEL);
    response = kmalloc(RESPONSE_SIZE, GFP_KERNEL);
    if (!request || !response) {
        result = -ENOMEM;
        goto cleanup;
    }

    initialize_request(request, phy->number, CMD_GET_PHY_EVENT_COUNTS);

    result = execute_task(request, response);
    if (result < 0)
        goto cleanup;

    phy->disparity_errors = get_field_from_response(response, DISPARITY_ERRORS);
    phy->loss_of_dword_sync = get_field_from_response(response, LOSS_OF_DWORD_SYNC);
    phy->invalid_dword = get_field_from_response(response, INVALID_DWORD);
    phy->running_disparity_error = get_field_from_response(response, RUNNING_DISPARITY_ERROR);
    phy->idle_errors = get_field_from_response(response, IDLE_ERRORS);

cleanup:
    kfree(request);
    kfree(response);
    return result;
}

int get_sas_phy_event_counts(struct sas_phy *phy) {
    void *request;
    void *response;
    int result;

    request = kmalloc(sizeof(*request), GFP_KERNEL);
    if (!request)
        return -ENOMEM;

    response = kmalloc(sizeof(*response), GFP_KERNEL);
    if (!response) {
        kfree(request);
        return -ENOMEM;
    }

    /* Initialize the request with appropriate command and PHY number */
    initialize_request(request, phy->number);

    result = execute_task(phy, request, response);
    if (result < 0)
        goto cleanup;

    /* Update the PHY structure with error counts from the response */
    phy->error_counts.correctable = get_correctable_errors(response);
    phy->error_counts.fec = get_fec_errors(response);
    phy->error_counts.recovered = get_recovered_errors(response);

cleanup:
    kfree(request);
    kfree(response);
    return result;
}
